<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { active, date, size, stateNames, useWorkspace } from './workspace'
import type { Task } from './types'
import { initializeLanguage, language, setLanguage, storageWarning, supported, t, safeText } from './i18n'
initializeLanguage()
const w = reactive(useWorkspace())
const pairingDownload = ref<HTMLButtonElement>()
watch(() => w.pairing?.session_id, sessionID => {
  if (!sessionID || !pairingDownload.value) return
  pairingDownload.value.scrollIntoView({ block: 'center', inline: 'nearest' })
  pairingDownload.value.focus({ preventScroll: true })
}, { flush: 'post' })
const navigation = computed(() => [ { id: 'devices', icon: '▦', title: t('web.ui.devices'), description: t('web.ui.device.status.and.system.environment') }, { id: 'sessions', icon: '◎', title: t('web.ui.sessions'), description: t('web.ui.authorization.scope.and.pairing') }, { id: 'tasks', icon: '↗', title: t('web.ui.tasks.and.approvals'), description: t('web.ui.from.plans.to.verifiable.results') }, { id: 'config', icon: '⚙', title: t('web.ui.configuration'), description: t('web.ui.runtime.limits.and.retention') }, { id: 'audit', icon: '≡', title: t('web.ui.audit'), description: t('web.ui.a.record.of.every.operation') } ])
const page = computed(() => navigation.value.find(n => n.id === w.view)!)
const configFields = computed<{ key: keyof NonNullable<typeof w.configDraft>; name: string; hint: string; min: number; max: number }[]>(() => [
  { key: 'max_concurrency', name: t('web.ui.maximum.concurrent.tasks'), hint: t('web.ui.concurrency.limit.shared.by.all.devices'), min: 1, max: 32 },
  { key: 'task_timeout_seconds', name: t('web.ui.default.task.timeout.seconds'), hint: t('web.ui.default.time.limit.for.new.tasks'), min: 1, max: 7200 },
  { key: 'pairing_ttl_seconds', name: t('web.ui.pairing.validity.seconds'), hint: t('web.ui.validity.window.for.single.use.pairing.credentials'), min: 30, max: 3600 },
  { key: 'session_ttl_seconds', name: t('web.ui.session.authorization.seconds'), hint: t('web.ui.task.authorization.duration.after.connection'), min: 60, max: 86400 },
  { key: 'heartbeat_ttl_seconds', name: t('web.ui.heartbeat.timeout.seconds'), hint: t('web.ui.authorization.is.revoked.after.this.timeout'), min: 20, max: 300 },
  { key: 'log_max_bytes', name: t('web.ui.task.log.limit.bytes'), hint: t('web.ui.logs.are.marked.truncated.at.the.limit'), min: 1024, max: 1048576 },
  { key: 'retention_days', name: t('web.ui.log.and.audit.retention.days'), hint: t('web.ui.expired.data.is.removed.by.server.policy'), min: 1, max: 365 },
])
function label(value: string) { return value === 'success' ? t('web.state.success') : stateNames[value] ? t(stateNames[value]!) : value }
function tone(value: string) { return ['online', 'succeeded', 'approved'].includes(value) ? 'good' : ['failed', 'rejected', 'timed_out'].includes(value) ? 'bad' : ['unknown', 'cleanup_pending', 'pending', 'pending_approval'].includes(value) ? 'warn' : 'neutral' }
function deviceName(id: string) { return w.devices.find(d => d.id === id)?.hostname ?? id }
function packageName(id?: string) { return w.catalog.find(c => c.id === id)?.name ?? id ?? t('web.ui.system.environment.inspection') }
function switchLanguage(event: Event) {
  const value = (event.target as HTMLSelectElement).value
  if (supported(value)) { if (!w.authenticated) w.token = ''; setLanguage(value) }
}
function planStep(step: string) { return ['validate_authorization', 'inspect_system', 'verify_artifact', 'install_pinned_package', 'verify_version'].includes(step) ? t('web.step.' + step) : step }
const auditActions = new Set(['login', 'config_updated', 'session_created', 'pairing_regenerated', 'plan_created', 'approval_requested', 'approval_approved', 'approval_rejected', 'task_created', 'session_revoked', 'task_cancel', 'worker_registered', 'cleanup_failed', 'cleanup_completed', 'pairing_expired', 'task_finished'])
function auditAction(value: string) { return auditActions.has(value) ? t('web.audit.' + value) : value }
function actor(value: string) { return ['operator', 'system', 'worker'].includes(value) ? t('web.actor.' + value) : value }
function taskError(task: Task) {
  const explanation = t('web.task.error.code', t('web.task.error.' + task.error_code), task.error_code ?? '—')
  return task.error_message ? t('web.task.error.detail', explanation, safeText(task.error_message)) : explanation
}
</script>

<template>
  <div v-if="!w.authenticated" class="login-page">
    <section class="login-story">
      <a class="brand" href="/" :aria-label="t('web.ui.remoteops.home')"><span class="brand-icon">R</span><strong>RemoteOps<span>{{ t('web.ui.remote.operations.workspace') }}</span></strong></a>
      <div class="story-content"><div class="eyebrow light">CONTROLLED. CONNECTED.</div><h1>{{ t('web.ui.every.connection') }}<br>{{ t('web.ui.within.your.authorization') }}</h1><p>{{ t('web.ui.connect.windows.devices.and.inspect.their.environment') }}<br>{{ t('web.ui.track.software.installation.from.planning.and.approval.to.verifi') }}</p><div class="story-flow"><span>{{ t('web.ui.01.local.consent') }}</span><i></i><span>{{ t('web.ui.02.operator.approval') }}</span><i></i><span>{{ t('web.ui.03.result.verification') }}</span></div></div>
      <div class="story-footer"><span class="live-dot"></span>{{ t('web.ui.local.management.temporary.authorization.auditable') }}</div>
    </section>
    <section class="login-panel"><form class="login-form" @submit.prevent="w.login">
      <label class="language-select"><span>{{ t('web.language') }}</span><select :value="language" @change="switchLanguage"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></label><p v-if="storageWarning" class="inline-note warning" role="status">{{ t('web.storage.warning') }}</p><div class="eyebrow">OPERATOR ACCESS</div><h2>{{ t('web.ui.sign.in.to.workspace') }}</h2><p class="muted">{{ t('web.ui.use.the.management.token.configured.when.controller.starts') }}</p>
      <label for="admin-token">{{ t('web.ui.management.token') }}</label><input id="admin-token" v-model="w.token" type="password" autocomplete="off" spellcheck="false" :placeholder="t('web.ui.enter.management.token')" required :disabled="w.busy">
      <div v-if="w.error" class="alert error" role="alert">{{ w.error }}</div>
      <button class="primary login-button" :disabled="w.busy || !w.token.trim()">{{ w.busy ? t('web.ui.verifying') : t('web.ui.enter.workspace') }} <span>→</span></button>
      <p class="login-note">{{ t('web.ui.the.token.is.used.for.this.sign.in.only.the.signed.in.operator.e') }}</p>
    </form><span class="login-version">{{ t('web.ui.remoteops.windows.installation.management') }}</span></section>
  </div>

  <div v-else class="workspace">
    <aside class="sidebar">
      <a class="brand" href="/" @click.prevent="w.view = 'devices'"><span class="brand-icon">R</span><strong>RemoteOps<span>{{ t('web.ui.remote.operations.workspace') }}</span></strong></a>
      <div class="nav-caption">{{ t('web.ui.workspace') }}</div>
      <nav :aria-label="t('web.ui.main.navigation')"><button v-for="item in navigation" :key="item.id" :class="{ selected: w.view === item.id }" :aria-current="w.view === item.id ? 'page' : undefined" @click="w.view = item.id"><span class="nav-icon">{{ item.icon }}</span>{{ item.title }}<span v-if="item.id === 'tasks' && w.pendingApprovals.length" class="nav-count">{{ w.pendingApprovals.length }}</span></button></nav>
      <div class="sidebar-bottom"><div class="operator"><span class="avatar">OP</span><div><strong>{{ t('web.ui.operator') }}</strong><small>{{ t('web.ui.secure.browser.session') }}</small></div></div><button class="logout" :disabled="w.busy" @click="w.logout">{{ t('web.ui.sign.out') }} <span>↗</span></button></div>
    </aside>

    <main class="main-content">
      <header class="topbar"><label class="language-select"><span>{{ t('web.language') }}</span><select :value="language" @change="switchLanguage"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></label><div class="breadcrumb">{{ t('web.ui.workspace') }} <span>/</span> {{ page.title }}</div><div class="connection"><span class="live-dot"></span>Controller <span class="connection-caption">{{ t('web.ui.local.management') }}</span></div></header>
      <div class="content"><p v-if="storageWarning" class="inline-note warning" role="status">{{ t('web.storage.warning') }}</p>
        <div class="page-heading"><div><div class="eyebrow">{{ w.view.toUpperCase() }} / WORKSPACE</div><h1>{{ page.title }}</h1><p class="muted">{{ page.description }}</p></div><div class="refresh-block"><small>{{ w.loading ? t('web.ui.syncing') : w.lastUpdated ? t('web.updated', w.lastUpdated) : t('web.ui.waiting.for.first.sync') }}</small><button class="secondary" :disabled="w.loading || w.busy" @click="w.error = ''; w.refresh()"><span :class="{ spinning: w.loading }">↻</span> {{ t('web.ui.refresh') }}</button></div></div>
        <div v-if="w.error" class="alert error" role="alert"><span>{{ w.error }}</span><button :aria-label="t('web.ui.dismiss.error')" @click="w.error = ''">×</button></div>
        <div v-if="w.notice" class="alert success" role="status"><span>{{ w.notice }}</span><button :aria-label="t('web.ui.dismiss.notification')" @click="w.notice = ''">×</button></div>
        <div v-if="w.loading && !w.lastUpdated" class="loading-state" role="status"><span class="spinner"></span>{{ t('web.ui.loading.workspace.data') }}</div>

        <template v-if="w.view === 'devices'">
          <div class="stats"><div class="stat"><span>{{ t('web.ui.connected.devices') }}</span><strong>{{ w.devices.length.toString().padStart(2, '0') }}</strong><small>{{ t('web.ui.windows.devices') }}</small></div><div class="stat"><span>{{ t('web.ui.online.and.authorized') }}</span><strong class="green">{{ w.runnableDevices.length.toString().padStart(2, '0') }}</strong><small><span class="live-dot"></span> {{ t('web.ui.ready.for.tasks') }}</small></div><div class="stat"><span>{{ t('web.ui.active.tasks') }}</span><strong>{{ w.tasks.filter(t => ['queued', 'running'].includes(t.state)).length.toString().padStart(2, '0') }}</strong><small>{{ t('web.ui.maximum.concurrency') }} {{ w.config?.max_concurrency ?? '—' }}</small></div><div class="stat"><span>{{ t('web.ui.awaiting.operator.approval') }}</span><strong>{{ w.pendingApprovals.length.toString().padStart(2, '0') }}</strong><small>{{ t('web.ui.runs.after.operator.confirmation') }}</small></div></div>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.device.list') }} <span class="count">{{ w.devices.length }}</span></h2><p>{{ t('web.ui.device.status.updates.every.5.seconds') }}</p></div><div class="toolbar"><input v-model="w.search" class="search" type="search" :aria-label="t('web.ui.search.devices')" :placeholder="t('web.ui.search.name.id.or.operating.system')"><button class="primary" @click="w.view = 'sessions'">{{ t('web.ui.create.pairing') }}</button></div></div>
            <div v-if="!w.devices.length && !w.loading" class="empty"><span class="empty-icon">▦</span><h3>{{ t('web.ui.no.connected.devices') }}</h3><p>{{ t('web.ui.create.a.session.and.give.the.pairing.bundle.to.the.device.user') }}<br>{{ t('web.ui.the.device.appears.here.after.local.consent') }}</p><button class="secondary" @click="w.view = 'sessions'">{{ t('web.ui.create.your.first.session') }}</button></div>
            <div v-else-if="!w.filteredDevices.length && !w.loading" class="empty"><h3>{{ t('web.ui.no.matching.devices') }}</h3><p>{{ t('web.ui.try.another.device.name.or.id') }}</p></div>
            <div v-else class="table-scroll"><table class="action-table"><thead><tr><th>{{ t('web.ui.devices') }}</th><th>{{ t('web.ui.system.client') }}</th><th>{{ t('web.ui.status') }}</th><th>{{ t('web.ui.last.heartbeat') }}</th><th>{{ t('web.ui.actions') }}</th></tr></thead><tbody><tr v-for="device in w.filteredDevices" :key="device.id"><td><div class="device-name"><span class="device-icon">▦</span><div><strong>{{ device.hostname }}</strong><small class="mono">{{ device.id }}</small></div></div></td><td>{{ device.os }}<small>Worker {{ device.client_version }}</small></td><td><span class="badge" :class="device.online ? 'good' : 'neutral'">{{ device.online ? t('web.ui.online') : t('web.ui.offline') }}</span><small v-if="!active(w.sessions.find(s => s.id === device.session_id))">{{ t('web.ui.authorization.unavailable') }}</small></td><td>{{ date(device.last_heartbeat) }}</td><td><button class="text-button" @click="w.selectedDeviceID = device.id">{{ t('web.ui.view.details') }}</button></td></tr></tbody></table></div>
          </section>
          <section v-if="w.selectedDevice" class="card detail-card"><div class="card-heading"><div><h2>{{ w.selectedDevice.hostname }}</h2><p class="mono">{{ w.selectedDevice.id }} · {{ w.selectedDevice.address }}</p></div><button class="text-button" @click="w.selectedDeviceID = ''">{{ t('web.ui.collapse') }}</button></div><div class="detail-body"><div class="info-grid"><div><span>{{ t('web.ui.linked.session') }}</span><strong class="mono">{{ w.selectedDevice.session_id }}</strong></div><div><span>{{ t('web.ui.connected.at') }}</span><strong>{{ date(w.selectedDevice.connected_at) }}</strong></div><div><span>{{ t('web.ui.operating.system') }}</span><strong>{{ w.selectedDevice.info?.os ?? w.selectedDevice.os }}</strong></div><div><span>{{ t('web.ui.cpu.memory') }}</span><strong>{{ w.selectedDevice.info?.cpu ?? t('web.ui.not.inspected') }} / {{ w.selectedDevice.info ? size(w.selectedDevice.info.memory_bytes) : '—' }}</strong></div><div><span>{{ t('web.ui.permission.status') }}</span><strong>{{ w.selectedDevice.info ? w.selectedDevice.info.elevated ? t('web.ui.elevated') : t('web.ui.standard.permissions') : t('web.ui.not.inspected') }}</strong></div></div><template v-if="w.selectedDevice.info"><h3>{{ t('web.ui.disks.and.graphics') }}</h3><div class="chips"><span v-for="disk in w.selectedDevice.info.disks" :key="disk.name">{{ disk.name }} · {{ size(disk.free_bytes) }} {{ t('web.ui.free') }} {{ size(disk.total_bytes) }}</span><span v-for="gpu in w.selectedDevice.info.gpus" :key="gpu.name">{{ gpu.name }} · {{ gpu.driver }}</span></div><h3>{{ t('web.ui.detected.software.versions') }}</h3><div class="chips"><span v-for="(version, id) in w.selectedDevice.info.software" :key="id">{{ packageName(String(id)) }} · {{ version }}</span></div></template><div class="actions"><button class="secondary" :disabled="w.busy || !w.runnableDevices.some(d => d.id === w.selectedDevice?.id)" @click="w.prepare(w.selectedDevice, 'inspect_system')">{{ t('web.ui.plan.system.inspection') }}</button><button class="primary" :disabled="w.busy || !w.runnableDevices.some(d => d.id === w.selectedDevice?.id)" @click="w.prepare(w.selectedDevice, 'install_package')">{{ t('web.ui.plan.software.installation') }}</button></div></div></section>
        </template>

        <template v-if="w.view === 'sessions'">
          <div class="two-column"><section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.create.authorized.session') }}</h2><p>{{ t('web.ui.define.the.scope.before.connecting') }}</p></div><span class="step-marker">01</span></div><form class="form-body" @submit.prevent="w.createSession"><fieldset :disabled="w.busy"><legend>{{ t('web.ui.allowed.tasks') }}</legend><label class="check-row"><input v-model="w.scope.allowed_tasks" type="checkbox" value="inspect_system"><span><strong>{{ t('web.ui.inspect.system.environment') }}</strong><small>{{ t('web.ui.operating.system.hardware.and.catalog.software.versions') }}</small></span></label><label class="check-row"><input v-model="w.scope.allowed_tasks" type="checkbox" value="install_package"><span><strong>{{ t('web.ui.install.catalog.software') }}</strong><small>{{ t('web.ui.only.selected.software.and.pinned.versions') }}</small></span></label><template v-if="w.scope.allowed_tasks.includes('install_package')"><div class="field-title">{{ t('web.ui.allowed.software') }}</div><div v-if="!w.catalog.length" class="inline-note">{{ t('web.ui.the.catalog.is.empty.configure.maintained.software.entries.local') }}</div><label v-for="entry in w.catalog" :key="entry.id" class="check-row"><input v-model="w.scope.allowed_packages" type="checkbox" :value="entry.id"><span><strong>{{ entry.name }} <span class="muted">{{ entry.version }}</span></strong><small>{{ entry.installer }}{{ entry.requires_admin ? ' ' + t('web.ui.requires.administrator.permissions') : '' }}</small></span></label><label class="check-row permission"><input v-model="w.scope.allow_admin" type="checkbox"><span><strong>{{ t('web.ui.allow.administrator.permission.requests') }}</strong><small>{{ t('web.ui.the.device.user.must.still.confirm.uac.locally.when.needed') }}</small></span></label></template></fieldset><div class="inline-note">{{ t('web.ui.pairing.validity') }} {{ Math.round((w.config?.pairing_ttl_seconds ?? 600) / 60) }} {{ t('web.ui.minutes.authorization.after.connection') }} {{ Math.round((w.config?.session_ttl_seconds ?? 3600) / 60) }} {{ t('web.ui.minutes') }}<br>{{ t('web.ui.scheduling.stops.when.authorization.expires.closes.or.loses.conn') }}</div><button class="primary full-width" :disabled="w.busy || !w.scope.allowed_tasks.length">{{ w.busy ? t('web.ui.processing') : t('web.ui.create.session.and.download.pairing.file') }} →</button></form></section>
            <section class="card pairing-card"><div class="card-heading"><div><h2>{{ w.pairing ? t('web.ui.pairing.file.generated') : t('web.ui.pairing.file') }}</h2><p>{{ t('web.ui.download.the.json.file.and.give.it.to.the.device.user') }}</p></div><span class="step-marker">02</span></div><div v-if="w.pairing" class="form-body"><span class="badge good">{{ t('web.ui.generated.single.use') }}</span><div class="pairing-download"><button ref="pairingDownload" class="primary full-width" @click="w.exportPairing">{{ t('web.ui.download.pairing.json') }}</button><p>{{ t('web.ui.the.file.is.saved.to.the.browser.download.directory') }}</p></div><h3>{{ w.pairing.controller_name }}</h3><div class="info-grid single"><div><span>{{ t('web.ui.session.id') }}</span><strong class="mono">{{ w.pairing.session_id }}</strong></div><div><span>{{ t('web.ui.controller.address') }}</span><strong>{{ w.pairing.controller_url }}</strong></div><div><span>{{ t('web.ui.pairing.deadline') }}</span><strong>{{ date(w.pairing.expires_at) }}</strong></div><div><span>{{ t('web.ui.authorization.after.connection') }}</span><strong>{{ w.pairing.authorization_seconds }} {{ t('web.ui.seconds') }}</strong><small class="muted">{{ t('web.ui.fixed.at.creation.timing.starts.after.device.consent.and.connect') }}</small></div></div><div class="inline-note">{{ t('web.ui.the.bundle.contains.temporary.credentials.and.stays.only.on.this') }}</div><button class="text-button full-width" @click="w.pairing = undefined">{{ t('web.ui.clear.pairing.bundle.from.page') }}</button></div><div v-else class="empty"><span class="empty-icon">◎</span><h3>{{ t('web.ui.waiting.for.a.session') }}</h3><p>{{ t('web.ui.new.sessions.automatically.download.a.pairing.file') }}<br>{{ t('web.ui.pending.sessions.can.regenerate.and.download.a.file.below') }}</p></div></section></div>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.authorized.sessions') }} <span class="count">{{ w.sessions.length }}</span></h2><p>{{ t('web.ui.unexpired.pending.sessions.can.download.a.pairing.file.regenerat') }}</p></div></div><div v-if="!w.sessions.length && !w.loading" class="empty"><h3>{{ t('web.ui.no.sessions') }}</h3><p>{{ t('web.ui.create.a.session.above.to.start.pairing') }}</p></div><div v-else class="table-scroll"><table class="action-table"><thead><tr><th>{{ t('web.ui.session.device') }}</th><th>{{ t('web.ui.authorization.scope') }}</th><th>{{ t('web.ui.status') }}</th><th>{{ t('web.ui.deadline') }}</th><th>{{ t('web.ui.actions') }}</th></tr></thead><tbody><tr v-for="session in w.sessions" :key="session.id"><td><strong class="mono">{{ session.id }}</strong><small>{{ session.device_id ? deviceName(session.device_id) : t('web.ui.awaiting.device.pairing') }}</small></td><td><span>{{ session.scope.allowed_tasks.map(taskType => taskType === 'inspect_system' ? t('web.ui.inspection') : t('web.ui.installation')).join(' / ') }}</span><small>{{ session.scope.allowed_packages.length }} {{ t('web.ui.packages') }} {{ session.scope.allow_admin ? t('web.ui.elevation.requests.allowed') : t('web.ui.standard.permissions') }}</small></td><td><span class="badge" :class="tone(session.state)">{{ label(session.state) }}</span><small v-if="session.state === 'cleanup_pending'" class="error-text">{{ t('web.session.cleanup.pending') }}</small></td><td>{{ date(session.state === 'pending_pair' ? session.pairing_expires_at : session.expires_at) }}<small>{{ session.state === 'pending_pair' ? t('web.ui.pairing.deadline') : t('web.ui.authorization.deadline') }}</small></td><td><div class="row-actions"><button v-if="w.canDownloadPairing(session)" class="text-button" :disabled="w.busy" @click="w.downloadSessionPairing(session)">↓ {{ w.pairing?.session_id === session.id ? t('web.ui.download.pairing.file') : t('web.ui.regenerate.and.download') }}</button><button v-if="session.state === 'cleanup_pending'" class="text-button" :disabled="w.busy" @click="w.sessionAction(session, 'retry-cleanup')">{{ t('web.ui.retry.node.cleanup') }}</button><button v-else-if="!['closed', 'expired', 'failed'].includes(session.state)" class="text-button danger" :disabled="w.busy || session.state === 'revoking'" @click="w.sessionAction(session, 'close')">{{ t('web.ui.close.session') }}</button><span v-else class="muted">—</span></div></td></tr></tbody></table></div></section>
        </template>

        <template v-if="w.view === 'tasks'">
          <div class="workflow-strip"><span><b>1</b> {{ t('web.ui.create.plan') }}</span><i>→</i><span><b>2</b> {{ t('web.ui.request.approval') }}</span><i>→</i><span><b>3</b> {{ t('web.ui.operator.confirmation') }}</span><i>→</i><span><b>4</b> {{ t('web.ui.execute.and.verify') }}</span></div>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.plan.a.new.task') }}</h2><p>{{ t('web.ui.validate.parameters.and.authorization.first.creating.a.plan.does') }}</p></div></div><form class="form-body task-form" @submit.prevent="w.createPlan"><label>{{ t('web.ui.target.device') }}<select v-model="w.taskDraft.device_id" required :disabled="w.busy" @change="w.taskDraft.package_id = ''"><option value="">{{ t('web.ui.select.an.authorized.online.device') }}</option><option v-for="device in w.runnableDevices" :key="device.id" :value="device.id">{{ device.hostname }} · {{ device.id }}</option></select></label><label>{{ t('web.ui.task.type') }}<select v-model="w.taskDraft.type" :disabled="w.busy"><option value="inspect_system">{{ t('web.ui.inspect.system.environment') }}</option><option value="install_package">{{ t('web.ui.install.catalog.software') }}</option></select></label><label v-if="w.taskDraft.type === 'install_package'">{{ t('web.ui.software.and.pinned.version') }}<select v-model="w.taskDraft.package_id" required :disabled="w.busy || !w.taskDraft.device_id"><option value="">{{ t('web.ui.select.software.authorized.by.the.session') }}</option><option v-for="entry in w.allowedCatalog" :key="entry.id" :value="entry.id">{{ entry.name }} {{ entry.version }}{{ entry.requires_admin ? ' ' + t('web.ui.administrator.permissions') : '' }}</option></select></label><label>{{ t('web.ui.timeout.seconds') }}<input v-model.number="w.taskDraft.timeout_seconds" type="number" min="1" max="7200" required :disabled="w.busy"></label><button class="primary" :disabled="w.busy || !w.taskDraft.device_id">{{ t('web.ui.generate.plan') }}</button><p v-if="!w.runnableDevices.length" class="form-note">{{ t('web.ui.no.authorized.online.devices.create.a.session.and.complete.pairi') }}</p><p v-else-if="w.draftSession" class="form-note">{{ t('web.ui.sessions') }} {{ w.draftSession.id }} · {{ w.draftSession.scope.allow_admin ? t('web.ui.local.administrator.requests.allowed') : t('web.ui.standard.permissions.only') }}</p></form></section>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.plans.and.approvals') }} <span class="count">{{ w.plans.length }}</span></h2><p>{{ t('web.ui.approval.binds.all.execution.parameters.changed.parameters.requi') }}</p></div></div><div v-if="!w.plans.length && !w.loading" class="empty"><h3>{{ t('web.ui.no.task.plans') }}</h3><p>{{ t('web.ui.review.generated.steps.here.and.request.approval') }}</p></div><div v-else class="plan-list"><article v-for="plan in w.plans" :key="plan.id" class="plan-item"><div class="plan-top"><div><h3>{{ packageName(plan.spec.package?.id) }} <span v-if="plan.spec.package" class="muted">{{ plan.spec.package.version }}</span></h3><p>{{ deviceName(plan.spec.device_id) }} · {{ plan.spec.type === 'install_package' ? t('web.ui.software.installation') : t('web.ui.system.inspection') }}</p></div><span class="badge" :class="tone(w.approvalFor(plan)?.status ?? 'pending')">{{ w.approvalFor(plan) ? w.approvalFor(plan)?.consumed_at ? t('web.ui.consumed') : label(w.approvalFor(plan)!.status) : t('web.ui.approval.not.requested') }}</span></div><div class="plan-parameters"><span>{{ t('web.ui.sessions') }} <strong class="mono">{{ plan.spec.session_id }}</strong></span><span>{{ t('web.ui.devices') }} <strong class="mono">{{ plan.spec.device_id }}</strong></span><span>{{ t('web.ui.timeout') }} <strong>{{ plan.spec.timeout_seconds }} {{ t('web.ui.seconds') }}</strong></span><span>{{ t('web.ui.administrator.permissions.174') }} <strong :class="{ 'error-text': plan.spec.requires_admin }">{{ plan.spec.requires_admin ? t('web.ui.local.confirmation.required') : t('web.ui.not.required') }}</strong></span><span>{{ t('web.ui.plan.deadline') }} <strong>{{ date(plan.expires_at) }}</strong></span><span v-if="w.approvalFor(plan)">{{ t('web.ui.approval.deadline') }} <strong>{{ date(w.approvalFor(plan)?.expires_at) }}</strong></span></div><ol class="plan-steps"><li v-for="(step, index) in plan.steps" :key="index">{{ planStep(step) }}</li></ol><details><summary>{{ t('web.ui.view.bound.digests') }}</summary><div class="digest">{{ t('web.ui.plan') }} {{ plan.id }}<br>{{ t('web.ui.task.digest') }} {{ plan.digest }}<br>{{ t('web.ui.catalog.digest') }} {{ plan.catalog_digest }}</div></details><div class="plan-actions"><button v-if="w.canRequest(plan)" class="secondary" :disabled="w.busy" @click="w.requestApproval(plan)">{{ t('web.ui.request.approval') }}</button><template v-if="w.approvalFor(plan) && w.canDecide(w.approvalFor(plan)!)"><button class="secondary danger" :disabled="w.busy" @click="w.decide(w.approvalFor(plan)!, 'reject')">{{ t('web.ui.reject') }}</button><button class="primary" :disabled="w.busy" @click="w.decide(w.approvalFor(plan)!, 'approve')">{{ t('web.ui.confirm.approval.of.this.plan') }}</button></template><button v-if="w.canExecute(plan)" class="primary" :disabled="w.busy" @click="w.execute(plan)">{{ t('web.ui.create.and.execute.task') }}</button><span v-if="new Date(plan.expires_at).getTime() <= Date.now()" class="muted">{{ t('web.ui.the.plan.has.expired.create.a.new.plan') }}</span></div></article></div></section>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.execution.tasks') }} <span class="count">{{ w.tasks.length }}</span></h2><p>{{ t('web.ui.verify.the.same.task.when.its.result.is.unknown.installation.is') }}</p></div></div><div v-if="!w.tasks.length && !w.loading" class="empty"><h3>{{ t('web.ui.no.execution.tasks') }}</h3><p>{{ t('web.ui.after.approval.select.create.and.execute.task') }}</p></div><div v-else class="table-scroll"><table class="action-table"><thead><tr><th>{{ t('web.ui.task.device') }}</th><th>{{ t('web.ui.content') }}</th><th>{{ t('web.ui.status') }}</th><th>{{ t('web.ui.created.at') }}</th><th>{{ t('web.ui.actions') }}</th></tr></thead><tbody><tr v-for="task in w.tasks" :key="task.id" :class="{ 'selected-row': task.id === w.selectedTaskID }"><td><strong class="mono">{{ task.id }}</strong><small>{{ deviceName(task.spec.device_id) }}</small></td><td>{{ packageName(task.spec.package?.id) }}<small>{{ task.spec.package?.version ?? t('web.ui.system.environment') }}</small></td><td><span class="badge" :class="tone(task.state)">{{ label(task.state) }}</span></td><td>{{ date(task.created_at) }}</td><td><button class="text-button" @click="w.selectTask(task.id)">{{ t('web.ui.status.and.logs') }}</button></td></tr></tbody></table></div></section>
          <section v-if="w.selectedTask" class="card"><div class="card-heading"><div><h2>{{ t('web.ui.task.details') }} <span class="badge" :class="tone(w.selectedTask.state)">{{ label(w.selectedTask.state) }}</span></h2><p class="mono">{{ w.selectedTask.id }}</p></div><div class="actions"><button v-if="['queued', 'running', 'unknown', 'pending_approval'].includes(w.selectedTask.state)" class="secondary danger" :disabled="w.busy" @click="w.cancelTask(w.selectedTask)">{{ t('web.ui.cancel.task') }}</button><button class="text-button" @click="w.selectedTaskID = ''">{{ t('web.ui.collapse') }}</button></div></div><div class="detail-body"><div v-if="w.selectedTask.state === 'unknown'" class="inline-note warning">{{ t('web.ui.the.execution.result.needs.verification.controller.queries.the.o') }}</div><div v-if="w.selectedTask.error_message" class="alert error">{{ taskError(w.selectedTask) }}</div><div class="info-grid"><div><span>{{ t('web.ui.started.finished') }}</span><strong>{{ date(w.selectedTask.started_at) }} / {{ date(w.selectedTask.finished_at) }}</strong></div><div><span>{{ t('web.ui.installer.exit.code') }}</span><strong>{{ w.selectedTask.result?.exit_code ?? '—' }}</strong></div><div><span>{{ t('web.ui.version.verification') }}</span><strong>{{ w.selectedTask.result ? w.selectedTask.result.verified ? t('web.verified', w.selectedTask.result.version ?? '') : t('web.ui.verification.failed') : t('web.ui.awaiting.result') }}</strong></div><div><span>{{ t('web.ui.restart.notice') }}</span><strong>{{ w.selectedTask.result?.reboot_required ? t('web.ui.manual.device.restart.required') : t('web.ui.no.restart.requested') }}</strong></div></div><details v-if="w.selectedTask.result?.info"><summary>{{ t('web.ui.view.system.inspection.result') }}</summary><pre class="system-json">{{ JSON.stringify(w.selectedTask.result.info, null, 2) }}</pre></details><div class="log-heading"><h3>{{ t('web.ui.execution.logs') }}</h3><small>{{ t('web.ui.cursor') }} {{ w.logAfter }} {{ t('web.ui.showing.the.latest') }} {{ w.logs.length }} {{ t('web.ui.entries') }}</small></div><div v-if="w.logTruncated" class="inline-note warning">{{ t('web.ui.server.logs.reached.the.capacity.limit.some.output.was.truncated') }}</div><div class="log-view" role="log" :aria-label="t('web.ui.execution.logs')"><p v-if="!w.logs.length" class="log-placeholder">{{ w.logLoading ? t('web.ui.loading.logs') : t('web.ui.no.log.output') }}</p><div v-for="entry in w.logs" :key="entry.sequence" class="log-line"><span>{{ date(entry.timestamp) }}</span><b>{{ entry.stream }}</b><code>{{ entry.message }}</code></div></div><button class="secondary" :disabled="w.logLoading" @click="w.loadLogs">{{ w.logLoading ? t('web.ui.loading') : t('web.ui.load.subsequent.logs') }}</button></div></section>
        </template>

        <template v-if="w.view === 'config'"><section class="card language-card"><div class="form-body"><label class="language-select"><span>{{ t('web.language') }}</span><select :value="language" @change="switchLanguage"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></label><p class="inline-note">{{ t('web.language.scope') }}</p></div></section>
          <section class="card network-card"><div class="card-heading"><div><h2>{{ t('web.ui.tailscale.connection.status') }}</h2><p>{{ t('web.ui.local.tailscale.status.reported.by.controller') }}</p></div><span class="badge" :class="w.networkStatus.state === 'connected' ? 'good' : w.networkStatus.state === 'disconnected' ? 'warn' : 'neutral'">{{ w.networkStatus.state === 'connected' ? t('web.ui.connected') : w.networkStatus.state === 'disconnected' ? t('web.ui.disconnected') : t('web.ui.status.unavailable') }}</span></div><div class="detail-body"><div v-if="w.networkStatus.addresses?.length" class="chips"><span v-for="address in w.networkStatus.addresses" :key="address" class="mono">{{ address }}</span></div><p v-if="w.networkStatus.state === 'connected'" class="muted">{{ t('web.ui.controller.is.connected.to.the.tailnet.devices.still.require.ses') }}</p><p v-else-if="w.networkStatus.state === 'disconnected'" class="muted">{{ t('web.ui.connect.tailscale.on.the.controller.device.then.refresh') }}</p><p v-else class="muted">{{ t('web.ui.tailscale.status.is.temporarily.unavailable.other.management.set') }}</p><div v-if="w.networkError" class="inline-note warning">{{ w.networkError }}</div></div></section>
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.runtime.configuration') }}</h2><p>{{ t('web.ui.controller.validates.settings.saved.values.are.confirmed.by.the') }}</p></div><span class="badge neutral">{{ t('web.ui.no.secrets.returned') }}</span></div><form v-if="w.configDraft" class="form-body" @submit.prevent="w.saveConfig"><div class="config-grid"><label v-for="field in configFields" :key="field.key">{{ field.name }}<input v-model.number="w.configDraft[field.key]" type="number" :min="field.min" :max="field.max" step="1" required :disabled="w.busy" @input="w.configDirty = true"><small>{{ field.hint }}</small></label></div><div class="config-footer"><span class="muted">{{ w.configDirty ? t('web.ui.unsaved.changes') : t('web.ui.configuration.synced') }}</span><button class="primary" :disabled="w.busy || !w.configDirty">{{ w.busy ? t('web.ui.saving') : t('web.ui.save.configuration') }}</button></div></form><div v-else class="empty"><h3>{{ w.loading ? t('web.ui.loading.configuration') : t('web.ui.configuration.unavailable') }}</h3><p>{{ t('web.ui.check.the.connection.and.refresh') }}</p></div></section>
          <div class="inline-note">{{ t('web.ui.the.catalog.is.maintained.locally.in.controller.and.fixed.within') }}</div>
        </template>

        <template v-if="w.view === 'audit'">
          <section class="card"><div class="card-heading"><div><h2>{{ t('web.ui.operation.audit') }} <span class="count">{{ w.audit.length }}</span></h2><p>{{ t('web.ui.records.actors.actions.linked.resources.and.results') }}</p></div><span class="badge neutral">{{ t('web.ui.retention') }} {{ w.config?.retention_days ?? '—' }} {{ t('web.ui.days') }}</span></div><div v-if="!w.audit.length && !w.loading" class="empty"><span class="empty-icon">≡</span><h3>{{ t('web.ui.no.audit.events') }}</h3><p>{{ t('web.ui.creation.approval.and.execution.actions.are.recorded.here') }}</p></div><div v-else class="table-scroll"><table><thead><tr><th>{{ t('web.ui.time') }}</th><th>{{ t('web.ui.actor') }}</th><th>{{ t('web.ui.action') }}</th><th>{{ t('web.ui.linked.resource') }}</th><th>{{ t('web.ui.result') }}</th></tr></thead><tbody><tr v-for="event in w.audit" :key="event.id"><td>{{ date(event.timestamp) }}</td><td>{{ actor(event.actor) }}</td><td><strong>{{ auditAction(event.action) }}</strong></td><td class="mono">{{ event.task_id ?? event.device_id ?? event.session_id ?? '—' }}<small v-if="event.task_id && event.session_id">{{ event.session_id }}</small></td><td><span class="badge" :class="tone(event.result)">{{ label(event.result) }}</span></td></tr></tbody></table></div></section>
        </template>
        <footer class="page-footer"><span>{{ t('web.ui.remoteops.controlled.remote.operations') }}</span><span>{{ t('web.ui.local.consent.operator.approval.execution.verification') }}</span></footer>
      </div>
    </main>
  </div>
</template>
